def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid', 0.0)))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 180:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2

    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2

    if supply <= 17:
        urgency += 2
    elif supply <= 20:
        urgency += 1

    if desperate_count >= 2:
        urgency += 1

    if budget < 90:
        urgency -= 1

    if urgency <= 1:
        base = 16.0 + (1.0 - supply_ratio) * 10.0
        if highest_prev >= 95:
            bid = min(base, 24.0)
        else:
            bid = max(base, min(highest_prev + 1.0, 34.0)) if highest_prev > 0 else base
    elif urgency <= 3:
        target = max(38.0, avg_prev * 0.72)
        if highest_prev >= 100:
            target = min(target, 58.0)
        else:
            target = max(target, highest_prev + 2.0 if highest_prev > 0 else 42.0)
        bid = target + (1.0 - supply_ratio) * 8.0
    elif urgency <= 5:
        target = max(62.0, avg_prev * 0.88)
        if highest_prev >= 105:
            target = max(72.0, highest_prev - 6.0)
        else:
            target = max(target, highest_prev + 3.0 if highest_prev > 0 else 68.0)
        bid = target + (1.0 - supply_ratio) * 10.0
    else:
        target = max(82.0, avg_prev * 0.96)
        if highest_prev >= 108:
            target = highest_prev + 1.5
        else:
            target = max(target, highest_prev + 4.0 if highest_prev > 0 else 88.0)
        bid = target + (1.0 - supply_ratio) * 12.0

    if rich_count >= 2 and urgency >= 4:
        bid += 4.0

    if day >= 8 and hp >= 6 and no_water == 0:
        bid -= 6.0

    max_safe = budget
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 1.2
        max_safe = max(0.0, budget - reserve)
        if max_safe <= 0:
            max_safe = min(budget, DAILY_SALARY * 0.8)
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6
        max_safe = max(0.0, budget - reserve)
        if max_safe <= 0:
            max_safe = budget

    bid = min(bid, max_safe)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    else:
        bid = min(my_status['budget'], avg_opp_bid * 1.05 + 5.0)

    return float(max(1.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    available_water_units = int(day_context['supply'] // WATER_REQ)

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    # --- Bidding Logic ---

    # Critical HP: Need water desperately
    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 1.1 # Base high bid
        if highest_prev_bid > DAILY_SALARY * 1.0: # If opponents are already very aggressive
            bid_amount = max(bid_amount, highest_prev_bid + 5)
        # If very late in the game and critical, bid almost all budget
        if day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] <= 1:
            bid_amount = max(bid_amount, my_status['budget'] * 0.95)
        return min(my_status['budget'], bid_amount)

    # Low HP: Need water soon
    elif my_status['hp'] <= 4:
        bid_amount = DAILY_SALARY * 0.9 # High bid
        if highest_prev_bid > DAILY_SALARY * 0.8:
            bid_amount = max(bid_amount, highest_prev_bid + 2)
        # If competition is high for available water, be more aggressive
        if available_water_units <= num_alive_opponents:
            bid_amount = max(bid_amount, DAILY_SALARY * 1.0) # Bid at least salary
        return min(my_status['budget'], bid_amount)

    # Good HP: Can afford to be strategic
    else:
        # Check if there's enough water for everyone (including me)
        is_water_scarce = (available_water_units < num_alive_opponents + 1)

        # Scenario A: Opponents were very aggressive yesterday
        if highest_prev_bid > DAILY_SALARY * 1.0: # Bids > 80
            if my_status['hp'] > 6 and is_water_scarce: # Very good HP, but water is scarce
                # Try to bait them to overspend, or save budget if they are too high.
                bid_amount = DAILY_SALARY * 0.4 # Low bid
            else: # Good HP, but not super high, or water is not that scarce
                # Stay competitive but try to save.
                bid_amount = max(DAILY_SALARY * 0.75, highest_prev_bid * 0.9)
            return min(my_status['budget'], bid_amount)

        # Scenario B: Opponents were moderately aggressive (similar to example's 0.85 threshold)
        elif highest_prev_bid >= DAILY_SALARY * 0.85: # Bids >= 68
            if is_water_scarce: # If water is tight, be more competitive
                bid_amount = max(DAILY_SALARY * 0.7, highest_prev_bid + 1.5)
            else: # If water is not scarce, try to save
                bid_amount = DAILY_SALARY * 0.6
            return min(my_status['budget'], bid_amount)

        # Scenario C: Opponents were low to moderate, or no previous bids
        else:
            if highest_prev_bid > 0: # Some previous bids, but not very high
                if is_water_scarce:
                    bid_amount = max(DAILY_SALARY * 0.6, highest_prev_bid + 2) # Be a bit more aggressive
                else:
                    bid_amount = max(DAILY_SALARY * 0.5, highest_prev_bid + 1) # Slightly above
            else: # No meaningful previous bids (e.g., Day 1)
                bid_amount = DAILY_SALARY * 0.65 # Initial competitive bid

            # If water is very abundant relative to competitors, bid lower
            if available_water_units > num_alive_opponents + 1:
                bid_amount = min(bid_amount, DAILY_SALARY * 0.4)

            return min(my_status['budget'], bid_amount)
